import { onMounted, onUnmounted } from "vue"
import { onGlobalEvent } from "@/composables/use-signalr-socket"
import { liveTarget } from "@/lib/machine-target"
import { useSessionsStore } from "@/stores/sessions"
import type { DomainEvent } from "@/lib/domain-events"
import { deriveSessionStatus } from "@/lib/session-status"
import { toScheduledRetry } from "@/lib/turn-retry"
import { toSessionInterruption } from "@/lib/session-interruption"
import { toSessionFailure } from "@/lib/session-failure"

/**
 * Subscribes to global "sessions" topic to receive activity_status events
 * and update the sessions store in real-time.
 */
export function useSessionActivityUpdates(): void {
  const sessionsStore = useSessionsStore()
  let unsubscribe: (() => void) | null = null

  onMounted(() => {
    unsubscribe = onGlobalEvent(liveTarget(), "sessions", (event: DomainEvent) => {
      // When Fleet tries a turn a limit stopped again: the session's row says so.
      if (event.type === "session.retry") {
        sessionsStore.patchSession(event.payload.sessionId, { scheduledRetry: toScheduledRetry(event.payload.retry) })
        return
      }

      // A page was shown, reopened or closed: the row's page count and newest page.
      if (event.type === "session.pages") {
        sessionsStore.patchSession(event.payload.sessionId, {
          pageCount: event.payload.pageCount,
          lastPageShownAt: event.payload.lastPageShownAt,
        })
        return
      }

      // A Fleet restart cut a turn off (or the user carried on): the session's row says so.
      if (event.type === "session.interrupted") {
        sessionsStore.patchSession(event.payload.sessionId, { interrupted: toSessionInterruption(event.payload.interruption) })
        return
      }

      // A turn failed, or a new one started after it: the session's row says so.
      if (event.type === "session.failure") {
        sessionsStore.patchSession(event.payload.sessionId, { failed: toSessionFailure(event.payload.failure) })
        return
      }

      if (event.type === "activity_status") {
        const payload = event.payload as {
          sessionId?: string
          activityStatus?: string
          capabilities?: unknown
          attempt?: number | null
          maxAttempts?: number | null
          message?: string | null
          next?: string | null
        }

        if (payload.sessionId && payload.activityStatus) {
          // Find the current session to check its current sessionStatus
          const currentSession = sessionsStore.sessions.find(
            (s) => s.session.id === payload.sessionId
          )

          // Derive the new sessionStatus from activityStatus, preserving lifecycle states
          const newSessionStatus = deriveSessionStatus(
            payload.activityStatus,
            currentSession?.sessionStatus
          )

          // Why and when a retrying session tries again, until it's working again.
          const retrying = payload.activityStatus === "retry"

          // Update both activityStatus and sessionStatus in the store
          sessionsStore.patchSession(payload.sessionId, {
            activityStatus: payload.activityStatus,
            sessionStatus: newSessionStatus,
            retryAttempt: retrying ? payload.attempt ?? null : null,
            retryMaxAttempts: retrying ? payload.maxAttempts ?? null : null,
            retryMessage: retrying ? payload.message ?? null : null,
            retryNext: retrying ? payload.next ?? null : null,
          })

          // Clear any optimistic busy state override
          sessionsStore.clearSessionStateOverride(payload.sessionId)
        }
      }
    })
  })

  onUnmounted(() => {
    if (unsubscribe) {
      unsubscribe()
    }
  })
}
/**
 * Maps activityStatus to sessionStatus following the server's DeriveSessionStatus logic.
 * Only maps activity-driven states; lifecycle states like "stopped", "completed", "error", "disconnected"
 * are preserved and not clobbered by activity events.
 *
 * Server mapping (SessionEndpoints.DeriveSessionStatus):
 * - If session.Status is "stopped" or "completed" → preserve it (lifecycle state)
 * - Otherwise:
 *   - activityStatus "idle" → sessionStatus "idle"
 *   - activityStatus "waiting_input" → sessionStatus "waiting_input"
 *   - activityStatus "busy"/"delegating"/"retry" → sessionStatus "active"
 */
export function deriveSessionStatus(activityStatus: string, currentSessionStatus?: string): string {
  // Preserve lifecycle states — don't clobber them with activity-driven states
  if (currentSessionStatus === "stopped" ||
      currentSessionStatus === "completed" ||
      currentSessionStatus === "error" ||
      currentSessionStatus === "disconnected") {
    return currentSessionStatus
  }

  // Map activity status to session status
  switch (activityStatus) {
    case "idle":
      return "idle"
    // A session stopped on a question needs the user, so it gets its own status rather than "active".
    case "waiting_input":
      return "waiting_input"
    case "busy":
    case "delegating":
    case "retry":
      return "active"
    default:
      // Unknown activity status — default to active to be safe
      return "active"
  }
}
