extern alias FakeLlm;

using FakeLlm::FakeLlmServer;
using Microsoft.Extensions.DependencyInjection;
using WeaveFleet.Application.Sessions;
using WeaveFleet.Domain.Events;
using WeaveFleet.Domain.Harnesses;
using WeaveFleet.Infrastructure.Users;
using Xunit.Abstractions;

namespace WeaveFleet.IntegrationTests.Harnesses.OpenCode2;

public sealed partial class OpenCode2LiveTests
{
    [OpenCode2Fact]
    public async Task DIAG_two_background_subagents_first_finishes_while_parent_and_sibling_work()
    {
        const string prompt = "Two helpers at once. (pair)";
        const string childA = "pair-child-a-quick";
        const string childB = "pair-child-b-slow";
        fleet.Answer(request =>
        {
            if (LlmRequest.Starts(request, childA))
                return new ScriptedLlmResponse { Text = "A done." };
            if (LlmRequest.Starts(request, childB))
                return ToolCall("call_pair_b_sleep", "shell", new { command = "sleep 20; echo b-slept", description = "B works" });
            if (LlmRequest.Continues(request, childB))
                return new ScriptedLlmResponse { Text = "B done." };
            if (LlmRequest.Starts(request, prompt))
                return new ScriptedLlmResponse
                {
                    StopReason = "tool_calls",
                    ToolCalls =
                    [
                        new ScriptedToolCall("call_pair_a", "subagent", System.Text.Json.JsonSerializer.Serialize(new { description = "Quick helper", prompt = childA, agent = "general", subagent_type = "general" })),
                        new ScriptedToolCall("call_pair_b", "subagent", System.Text.Json.JsonSerializer.Serialize(new { description = "Slow helper", prompt = childB, agent = "general", subagent_type = "general" })),
                    ],
                };
            if (LlmRequest.Continues(request, prompt) && LlmRequest.LastToolText(request) is { } tool && tool.Contains("parent-slept", StringComparison.Ordinal))
                return new ScriptedLlmResponse { Text = "Parent done." };
            if (LlmRequest.Continues(request, prompt))
                return ToolCall("call_pair_parent_sleep", "shell", new { command = "sleep 12; echo parent-slept", description = "Parent works" });
            if (request.Contains("<subagent", StringComparison.Ordinal))
                return new ScriptedLlmResponse { Text = "Noted." };
            return null;
        });

        using var cts = new CancellationTokenSource(TimeSpan.FromMinutes(3));
        var id = await fleet.CreateSessionAsync(fleet.NewFolder("pair"), "Pair", cts.Token);
        var events = fleet.WatchTopics(["sessions", $"session:{id}"], cts.Token);
        var started = DateTimeOffset.UtcNow;
        await PromptAsync(id, prompt, options: null, cts.Token);

        string Dump() => string.Join("\n", events.All
            .Where(e => e.Type.StartsWith("work.", StringComparison.Ordinal) || e.Type is "activity_status" or "session.idle")
            .Select(e => $"{(e.Timestamp - started).TotalSeconds,6:F1}s {e.Topic,-50} {e.Type,-16} {e.Payload.GetRawText()}"));

        for (var i = 0; i < 60; i++)
        {
            await Task.Delay(1000, cts.Token);
            var work = await Work2(id);
            output.WriteLine($"t+{(DateTimeOffset.UtcNow - started).TotalSeconds:F0}s work: {string.Join("; ", work.Select(w => $"{w.WorkId}:{(w.EndedReason ?? "running")}"))}");
            if (events.All.Any(e => e.Type == "session.idle" && e.Topic == $"session:{id}") && i > 30)
                break;
        }

        output.WriteLine(Dump());
        var delegations = await Delegations(id);
        output.WriteLine(string.Join("\n", delegations.Select(d => $"{d.ParentToolCallId} {d.Status} {d.ChildSessionId}")));
        true.ShouldBeFalse("diagnostic");
    }

    private async Task<IReadOnlyList<RunningWorkItem>> Work2(string sessionId)
    {
        using var user = BackgroundUserContext.BeginScope(OpenCode2LiveFleet.Owner);
        using var scope = fleet.Services.CreateScope();
        return await scope.ServiceProvider.GetRequiredService<DelegationService>().GetWorkAsync(sessionId);
    }
}

