content.content:
  let unsubscribe: Unsubscribe | null = null
  let unsubscribeActivity: Unsubscribe | null = null
  // Live events wait here for the next frame. A streamed reply sends a delta per token, each in its own socket
  // message; applying them one by one re-rendered the conversation for every token.
  const frameEvents: Array<{ event: DomainEvent; live: boolean }> = []
  let frameRequest: number | null = null
  let frameFallback: ReturnType<typeof setTimeout> | null = null
  // The session the state belongs to, once a snapshot of it has arrived.
  let snapshotSessionId: string | null = null

  const messages = computed<readonly AccumulatedMessage[]>(() => streamState.value.messages)
  const delegations = computed<readonly DelegationDto[]>(() => streamState.value.delegations)
  const sessionStatus = computed<SessionStreamStatus>(() => streamState.value.sessionStatus)
  const runningWork = computed<readonly RunningWorkItem[]>(() => streamState.value.runningWork)

  // The strip and the Agents tab read the session's work from use-running-work; the stream is its freshest source.
  // Only once the snapshot is in: the empty state while it loads would wipe what's known.
  watch(
    () => [snapshotSessionId === currentSessionId.value && !isLoading.value, streamState.value.runningWork] as const,
    ([loaded, items]) => {
      if (loaded) {
        publishRunningWork(currentSessionId.value, items)
      }
    },
  )

  // The ring by Send reads the session's context from use-session-context; once the snapshot is in, as for its work.
  watch(
    () => [snapshotSessionId === currentSessionId.value && !isLoading.value, streamState.value.context] as const,
    ([loaded, context]) => {
      if (loaded) {
        publishSessionContext(currentSessionId.value, context)
      }
    },
  )

  /** Keeps the state of the session being left, if it came from a snapshot. */
  function keepCurrentStream(): void {
    if (snapshotSessionId && !isLoading.value && streamState.value.messages.length > 0) {
      keepStream(keptKey(machine, snapshotSessionId), {
        state: streamState.value,
        hasMore: hasMore.value,
        cursor: cursor.value,
        isPartial: isPartial.value,
      })
    }
    snapshotSessionId = null
  }

  /** Shows the session's kept state while its snapshot loads, with the status the session list has now. */
  function showKeptStream(activeSessionId: string): void {
    const kept = keptStreams.get(keptKey(machine, activeSessionId))
    if (!kept) {
      return
    }

