    switched = true; log("navigate to other");
    await page.goto(`${base}/sessions/${other}`).catch((e) => log("nav fail " + e));
  }
  if (mode === "switchspa" && !switched && el > 12) {
    switched = true; log("click other in sidebar");
    await page.getByText("Other work").first().click().catch((e) => log("click fail " + e));
  }
  if (mode.startsWith("switch") && switched && !prompted1 && el > 16) {
    prompted1 = true; log("prompt other");
    const box = page.locator("textarea").first();
    await box.fill("hello again").catch((e) => log("fill fail " + e)); await box.press("Enter").catch(() => {});
  }
  if (mode.startsWith("switch") && switched && !prompted2 && el > 45) {
    prompted2 = true; log("prompt other 2");
    const box = page.locator("textarea").first();
    await box.fill("and again").catch((e) => log("fill fail " + e)); await box.press("Enter").catch(() => {});
  }
  await page.waitForTimeout(500);
}
await page.screenshot({ path: `${K}/watch-${mode}.png` });
await sample(); log("end");
await browser.close(); out.end();
